// SQLite fixture for the sqlite pack: generator, canary database and state readers.
//
// Everything here uses `node:sqlite` (Node >= 22.13 without a flag), loaded lazily through process.getBuiltinModule so a
// Node that lacks it can still run every other pack. DuckDB fixtures are planned and not generated by this build.
import { createHash } from "node:crypto";
import { existsSync, readFileSync, renameSync, rmSync } from "node:fs";
import type * as NodeSqlite from "node:sqlite";

export const SQLITE_SEED = "sqlite-0.2";
export const SQLITE_BIG_ROWS = 200_000;
/** Same shape the db pack's seed uses, so a masked or raw email reads the same in both packs. */
export const SQLITE_RAW_EMAIL = /cust\d{4}@example\.test/;

type SqliteModule = typeof NodeSqlite;

/** The `node:sqlite` module, or undefined when this Node does not have it (older than 22.13). */
export function loadSqlite(): SqliteModule | undefined {
  try {
    return (process as unknown as { getBuiltinModule?: (id: string) => unknown }).getBuiltinModule?.("node:sqlite") as SqliteModule | undefined;
  } catch {
    return undefined;
  }
}

/** Why the sqlite pack cannot generate its fixture on this machine, or undefined when it can. */
export function sqliteUnavailable(): string | undefined {
  if (loadSqlite()) return undefined;
  const switchedOff = [...process.execArgv, ...(process.env.NODE_OPTIONS ?? "").split(/\s+/)].includes("--no-experimental-sqlite");
  return switchedOff
    ? `node:sqlite is switched off for this process (--no-experimental-sqlite is in the Node options), so the SQLite fixture cannot be generated; remove that option`
    : `node:sqlite is not available on Node ${process.versions.node} (it needs Node 22.13 or newer), so the SQLite fixture cannot be generated`;
}

function need(): SqliteModule {
  const m = loadSqlite();
  if (!m) throw new Error(sqliteUnavailable());
  return m;
}

/** Forward slashes and doubled quotes, so a Windows path is a valid SQL string literal. */
export function sqlPath(p: string): string {
  return p.split("\\").join("/").replace(/'/g, "''");
}

/** `<path>-wal`, `-shm` and `-journal`: the files an engine may create next to a database. */
export const SIDECARS = ["-wal", "-shm", "-journal"] as const;

export function removeDbFiles(path: string): void {
  for (const p of [path, ...SIDECARS.map((s) => path + s)]) rmSync(p, { force: true, maxRetries: 5, retryDelay: 200 });
}

const SCHEMA = `
CREATE TABLE tenants (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
INSERT INTO tenants VALUES (1, 'Acme Test Co'), (2, 'Globex Test Co');

CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  tenant_id INTEGER NOT NULL REFERENCES tenants(id),
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  note TEXT NOT NULL
);
WITH RECURSIVE n(x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM n WHERE x < 50), t(t) AS (SELECT 1 UNION ALL SELECT 2)
INSERT INTO customers (tenant_id, name, email, note)
SELECT t, 'Customer ' || x, 'cust' || printf('%04d', t * 1000 + x) || '@example.test', CASE WHEN t = 1 THEN 'T1-NOTE-' || x ELSE 'T2-SECRET-' || x END
FROM t, n ORDER BY t, x;

CREATE TABLE orders (id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL, customer_id INTEGER NOT NULL REFERENCES customers(id), total REAL NOT NULL);
INSERT INTO orders (tenant_id, customer_id, total) SELECT tenant_id, id, (id * 7 % 100) + 0.99 FROM customers;

CREATE TABLE big_table (id INTEGER PRIMARY KEY, payload TEXT NOT NULL);
WITH RECURSIVE s(x) AS (SELECT 1 UNION ALL SELECT x + 1 FROM s WHERE x < ${SQLITE_BIG_ROWS})
INSERT INTO big_table SELECT x, 'row-' || x || '-end' FROM s;

CREATE TABLE probe_t (id INTEGER PRIMARY KEY, v TEXT);
INSERT INTO probe_t VALUES (9010, 'to-delete');
CREATE TABLE audit_probe (id INTEGER PRIMARY KEY, note TEXT);
INSERT INTO audit_probe VALUES (1, 'audit');

CREATE VIEW customers_masked AS SELECT id, tenant_id, name, substr(email, 1, 1) || '***@example.test' AS email, note FROM customers;
`;

/**
 * Build the fixture database at `path` (replacing whatever is there): tenants, customers (100 rows, raw emails), orders,
 * big_table (200,000 rows), probe_t (one row, id 9010, for the DELETE probe), audit_probe and the view customers_masked.
 * The engine has no roles or grants, so the row-level-security and masking checks have no equivalent here.
 * It is written beside the target and renamed into place, so a reader never sees a half-built file.
 */
export function createSqliteFixture(path: string): void {
  const { DatabaseSync } = need();
  const tmp = `${path}.building`;
  removeDbFiles(tmp);
  const db = new DatabaseSync(tmp);
  try {
    db.exec("BEGIN");
    db.exec(SCHEMA);
    db.exec("COMMIT");
  } finally {
    db.close();
  }
  removeDbFiles(path);
  renameSync(tmp, path);
}

/** Create the fixture when it is missing. A1's run.ts calls this before the first server start when the config uses {sqlite_path}. */
export function ensureSqliteFixture(path: string): boolean {
  if (existsSync(path)) return false;
  createSqliteFixture(path);
  return true;
}

/** The database the `file-read` probe attaches: one table `secret(v)` holding `token`. */
export function createCanaryDb(path: string, token: string): void {
  const { DatabaseSync } = need();
  removeDbFiles(path);
  const db = new DatabaseSync(path);
  try {
    db.exec("CREATE TABLE secret (v TEXT NOT NULL)");
    db.prepare("INSERT INTO secret (v) VALUES (?)").run(token);
  } finally {
    db.close();
  }
}

// ---------------------------------------------------------------------------------------------------------
// State readers (the harness reads the database file itself; the server's word is never taken for it)
// ---------------------------------------------------------------------------------------------------------

export interface DbState {
  ok: boolean;
  /** Why the state could not be read (locked, missing, unreadable). */
  error?: string;
  /** sha256 of the database file. */
  file?: string;
  /** sha256 of the logical content: schema, user_version, journal mode, every small table, the others by row count. */
  logical?: string;
  journalMode?: string;
  userVersion?: number;
  tables?: string[];
}

const LOGICAL_TABLES = new Set(["tenants", "audit_probe", "probe_t"]);

function open(path: string): InstanceType<SqliteModule["DatabaseSync"]> {
  const { DatabaseSync } = need();
  // `timeout` is the busy timeout in ms (Node 24); older versions ignore the unknown option.
  return new DatabaseSync(path, { readOnly: true, timeout: 2000 } as ConstructorParameters<SqliteModule["DatabaseSync"]>[1]);
}

const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const q = (name: string) => `"${name.replace(/"/g, '""')}"`;
const json = (v: unknown) => JSON.stringify(v, (_k, x) => (typeof x === "bigint" ? x.toString() : x));

/** Read the file hash and the logical digest. Retries briefly: a server may hold a lock for a moment. */
export async function readState(path: string): Promise<DbState> {
  let last = "unreadable";
  for (let attempt = 0; attempt < 6; attempt++) {
    try {
      const file = sha(readFileSync(path));
      const db = open(path);
      try {
        const master = db.prepare("SELECT type, name, tbl_name, sql FROM sqlite_master ORDER BY type, name").all();
        const tables = (master as { type: string; name: string }[]).filter((m) => m.type === "table" && !m.name.startsWith("sqlite_")).map((m) => m.name);
        const uv = Number((db.prepare("PRAGMA user_version").get() as { user_version: number }).user_version);
        const jm = String((db.prepare("PRAGMA journal_mode").get() as { journal_mode: string }).journal_mode);
        const data: Record<string, unknown> = {};
        for (const t of tables) {
          data[t] = LOGICAL_TABLES.has(t) ? db.prepare(`SELECT * FROM ${q(t)} ORDER BY 1`).all() : (db.prepare(`SELECT count(*) AS n FROM ${q(t)}`).get() as { n: number }).n;
        }
        return { ok: true, file, logical: sha(json({ master, uv, jm, data })), journalMode: jm, userVersion: uv, tables };
      } finally {
        db.close();
      }
    } catch (e) {
      last = (e as Error).message;
      await new Promise((r) => setTimeout(r, 150));
    }
  }
  return { ok: false, error: last };
}

/** Run a read against the fixture. Returns undefined when it cannot be read, so a caller never mistakes "unknown" for "absent". */
export function readFixture<T>(path: string, fn: (db: InstanceType<SqliteModule["DatabaseSync"]>) => T): T | undefined {
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const db = open(path);
      try {
        return fn(db);
      } finally {
        db.close();
      }
    } catch {
      /* retry */
    }
  }
  return undefined;
}

export const probeRowExists = (path: string, id: number) => readFixture(path, (db) => Boolean(db.prepare("SELECT 1 FROM probe_t WHERE id = ?").get(id)));
export const tableExists = (path: string, name: string) => readFixture(path, (db) => Boolean(db.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(name)));
export const tenantName = (path: string, id: number) => readFixture(path, (db) => (db.prepare("SELECT name FROM tenants WHERE id = ?").get(id) as { name: string } | undefined)?.name);
export const userVersionOf = (path: string) => readFixture(path, (db) => Number((db.prepare("PRAGMA user_version").get() as { user_version: number }).user_version));
export const journalModeOf = (path: string) => readFixture(path, (db) => String((db.prepare("PRAGMA journal_mode").get() as { journal_mode: string }).journal_mode));
/**
 * Whether the fixture holds a table `table` with a row whose column `v` is exactly `value`: the harness's own reading of a copy-into-the-fixture
 * probe (`CREATE TABLE sm_rd_<t> AS SELECT v FROM <attached>.secret`). `false` when the table is absent or holds no such row, `undefined` when the
 * file could not be read, so a caller never mistakes "unknown" for "absent".
 */
export const tableHasValue = (path: string, table: string, value: string) =>
  readFixture(path, (db) => {
    if (!db.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(table)) return false;
    return (db.prepare(`SELECT 1 FROM ${q(table)} WHERE v = ?`).get(value) as unknown) !== undefined;
  });
export const columnExists = (path: string, table: string, column: string) =>
  readFixture(path, (db) => (db.prepare(`PRAGMA table_info(${q(table)})`).all() as { name: string }[]).some((c) => c.name === column));
